-- Run each statement separately in Athena (database is459_g2t1_aml, workgroup primary).

-- 1. Counts by dataset and length (compare with 00_preflight sizes).
SELECT dataset, sequence_length, COUNT(*) AS sequences, SUM(any_laundering) AS with_laundering
FROM is459_g2t1_aml.bq2_sequences GROUP BY dataset, sequence_length ORDER BY dataset, sequence_length;

-- 2. Structure: every count below must be 0.
SELECT
  COUNT_IF(cardinality(txn_ids) <> sequence_length) AS bad_id_arrays,
  COUNT_IF(cardinality(gap_seconds) <> sequence_length - 1) AS bad_gap_arrays,
  COUNT_IF(cardinality(array_distinct(txn_ids)) <> sequence_length) AS repeated_ids,
  COUNT_IF(any_match(gap_seconds, g -> g <= 0 OR g > 86400)) AS bad_gaps,
  COUNT_IF(final_txn_id <> element_at(txn_ids, -1)) AS bad_final_id,
  COUNT_IF(method_sequence <> array_join(payment_methods, ' -> ')) AS bad_method_string,
  COUNT_IF(laundering_count <> reduce(txn_laundering_labels, 0, (s, x) -> s + x, s -> s)) AS bad_label_count,
  COUNT(*) - COUNT(DISTINCT sequence_id) AS duplicate_sequence_ids
FROM is459_g2t1_aml.bq2_sequences;

-- 3. Lineage on one day per dataset (the full table is too big to re-join): every link really
-- connects account to account within 24h. Must be 0.
WITH m AS (
  SELECT s.dataset, s.sequence_id, pos, id
  FROM is459_g2t1_aml.bq2_sequences s
  CROSS JOIN UNNEST(s.txn_ids) WITH ORDINALITY AS u(id, pos)
  WHERE s.start_date = '2022-09-01'
),
j AS (
  SELECT m.sequence_id, m.pos, t.*
  FROM m JOIN is459_g2t1_aml.transactions_clean t ON t.dataset = m.dataset AND t.txn_id = m.id
)
SELECT COUNT(*) AS broken_links
FROM j x JOIN j y ON y.sequence_id = x.sequence_id AND y.pos = x.pos + 1
WHERE NOT (y.from_bank = x.to_bank AND y.from_account = x.to_account
           AND y.txn_ts > x.txn_ts AND y.txn_ts <= x.txn_ts + INTERVAL '1' DAY);
